div.script:

const c = document.getElementById('c');
const ctx = c.getContext('2d');
let w, h;
const particles = [];
let windX = 0, windY = 0, windTime = 0, lastInteractionTime = 0;
let flameOffsetX = 0, flameOffsetY = 0, targetFlameX = 0, targetFlameY = 0;
let tiltX = 0, tiltY = 0;

function resize() {
    w = c.width = window.innerWidth;
    h = c.height = window.innerHeight;
}
window.addEventListener('resize', resize);
resize();

function applyWind(clientX, clientY) {
    const now = Date.now();
    if (now - lastInteractionTime > 1000) windTime = 15;
    lastInteractionTime = now;
    windX = (clientX - w/2) * 0.003;
    windY = (clientY - h/2) * 0.002;
    if (windTime > 0) {
        targetFlameX = (clientX - w/2) * 0.02;
        targetFlameY = (clientY - h/2) * 0.015;
    }
}

c.addEventListener('touchstart', (e) => { applyWind(e.touches[0].clientX, e.touches[0].clientY); e.preventDefault(); });
c.addEventListener('touchmove', (e) => { applyWind(e.touches[0].clientX, e.touches[0].clientY); e.preventDefault(); });
c.addEventListener('mousedown', (e) => { applyWind(e.clientX, e.clientY); });
c.addEventListener('mousemove', (e) => { if (e.buttons === 1) applyWind(e.clientX, e.clientY); });

if (window.DeviceOrientationEvent) {
    window.addEventListener('deviceorientation', (e) => {
        let gamma = e.gamma || 0;
        let beta = e.beta || 0;
        let multiplier = (Math.abs(beta) <= 90) ? -1 : 1;
        tiltX += (gamma * 0.1 * multiplier - tiltX) * 0.4;
    });
}

class P {
    constructor() { this.reset(); }
    reset() {
        this.x = w / 2;
        this.y = h / 2 + 60;
        this.vx = (Math.random() - 0.5) * 1.8;
        this.vy = (Math.random() * -2) - 1;
        this.life = 1.0;
        this.decay = (Math.random() * 0.015) + 0.008;
        this.size = (Math.random() * 20) + 20;
    }
    update() {
        this.life -= this.decay;
        if (this.life <= 0) { this.reset(); return; }
        this.x += this.vx;
        this.y += this.vy;
        if (windTime > 0) { this.vx += windX * 0.15; this.vy += windY * 0.1; }
        this.vx += (w/2 - this.x) * 0.005;
        this.size *= 0.98;
    }
    draw() {
        ctx.beginPath();
        let g = ctx.createRadialGradient(this.x, this.y, 0, this.x, this.y, this.size);
        let r = 255, gr = Math.floor(180 * this.life), b = Math.floor(50 * this.life);
        g.addColorStop(0, `rgba(255, 255, 200, ${this.life})`);
        g.addColorStop(0.5, `rgba(255, 150, 0, ${this.life})`);
        g.addColorStop(1, `rgba(${r}, ${gr}, ${b}, 0)`);
        ctx.fillStyle = g;
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fill();
    }
}

for(let i=0; i<250; i++) particles.push(new P());

function getBaseInfo() {
    const by = h / 2 + 95;
    const bx = w / 2;
    return { bx, by, size: 28 };
}

function drawBase(bx, by, size) {
    ctx.beginPath();
    let g = ctx.createLinearGradient(bx, by - size, bx, by + size);
    g.addColorStop(0, 'rgba(255, 255, 255, 1)');
    g.addColorStop(0.5, 'rgba(255, 100, 0, 1)');
    g.addColorStop(1, 'rgba(0, 50, 255, 0.8)');
    ctx.fillStyle = g;
    ctx.ellipse(bx, by, size, size * 1.5, 0, 0, Math.PI * 2);
    ctx.fill();
}

function anim() {
    ctx.clearRect(0, 0, w, h);
    const baseInfo = getBaseInfo();
    ctx.save();
    ctx.translate(baseInfo.bx, baseInfo.by + 20);
    ctx.transform(1, 0, -tiltX * 0.4, 1, 0, 0);
    ctx.translate(-baseInfo.bx, -baseInfo.by - 20);
    drawBase(baseInfo.bx, baseInfo.by, baseInfo.size);
    ctx.globalCompositeOperation = 'lighter';
    ctx.globalAlpha = 1.0; 
    for(let p of particles) { p.update(); p.draw(); }
    ctx.restore();
    if (windTime > 0) windTime--;
    requestAnimationFrame(anim);
}
anim();
